package com.example.sms;

import java.util.logging.Logger;

/**
 * Configuration class to load database connection details from environment variables.
 * Provides default values if environment variables are not set.
 */
public class Config {
    private static final Logger LOGGER = Logger.getLogger(Config.class.getName());

    public static final String DB_URL;
    public static final String DB_USER;
    public static final String DB_PASSWORD;

    static {
        // Load database URL from environment variable or use a default H2 file path
        DB_URL = getEnvOrDefault("SMS_DB_URL", "jdbc:h2:./data/sms_db");
        // Load database user from environment variable or use default 'sa' for H2
        DB_USER = getEnvOrDefault("SMS_DB_USER", "sa");
        // Load database password from environment variable or use an empty string for H2
        DB_PASSWORD = getEnvOrDefault("SMS_DB_PASSWORD", "");

        LOGGER.info("Database URL: " + DB_URL);
        LOGGER.info("Database User: " + DB_USER);
        // CRITICAL: Do not log DB_PASSWORD or any other sensitive information
        // LOGGER.info("Database Password: " + DB_PASSWORD); // This would be a security flaw
    }

    /**
     * Retrieves an environment variable's value, or a default if not set.
     *
     * @param envVarName The name of the environment variable.
     * @param defaultValue The default value to use if the environment variable is not found or is empty.
     * @return The value of the environment variable or the default value.
     */
    private static String getEnvOrDefault(String envVarName, String defaultValue) {
        String value = System.getenv(envVarName);
        if (value == null || value.isEmpty()) {
            LOGGER.warning("Environment variable '" + envVarName + "' not set. Using default value.");
            return defaultValue;
        }
        return value;
    }
}

