package com.example.sms.model;

/**
 * Represents a Student entity in the Student Management System.
 */
public class Student {
    private int id;
    private String name;
    private int age;
    private String grade;

    /**
     * Constructs a Student object with all details, including ID.
     * Used when retrieving students from the database.
     */
    public Student(int id, String name, int age, String grade) {
        this.id = id;
        this.name = name;
        this.age = age;
        this.grade = grade;
    }

    /**
     * Constructs a Student object without an ID.
     * Used when creating a new student, where the ID will be generated by the database.
     */
    public Student(String name, int age, String grade) {
        this(-1, name, age, grade); // ID will be generated by DB, -1 indicates not yet set
    }

    // Getters
    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public String getGrade() {
        return grade;
    }

    // Setters (useful for updating student information)
    public void setId(int id) {
        this.id = id;
    }

    public void setName(String name) {
        this.name = name;
    }

    public void setAge(int age) {
        this.age = age;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    @Override
    public String toString() {
        return "Student{" +
               "id=" + id +
               ", name='" + name + '\'' +
               ", age=" + age +
               ", grade='" + grade + '\'' +
               '}';
    }
}

