package com.example.sms.repository;

import com.example.sms.Config;
import com.example.sms.model.Student;
import com.example.sms.model.User;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Manages all database interactions for students and users.
 * Ensures the use of PreparedStatement for all SQL queries involving user input
 * to prevent SQL injection vulnerabilities.
 */
public class DatabaseManager {
    private static final Logger LOGGER = Logger.getLogger(DatabaseManager.class.getName());

    public DatabaseManager() {
        initializeDatabase();
    }

    /**
     * Establishes a connection to the database using configurations from the Config class.
     *
     * @return A new SQL Connection object.
     * @throws SQLException If a database access error occurs.
     */
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(Config.DB_URL, Config.DB_USER, Config.DB_PASSWORD);
    }

    /**
     * Initializes the database by creating necessary tables if they don't already exist.
     */
    private void initializeDatabase() {
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) { // Statement is safe here as no user input is involved

            // Create students table
            String createStudentsTableSQL = "CREATE TABLE IF NOT EXISTS students (" +
                                            "id INT AUTO_INCREMENT PRIMARY KEY," +
                                            "name VARCHAR(255) NOT NULL," +
                                            "age INT NOT NULL," +
                                            "grade VARCHAR(10) NOT NULL)";
            stmt.execute(createStudentsTableSQL);
            LOGGER.info("Students table ensured.");

            // Create users table for authentication
            String createUsersTableSQL = "CREATE TABLE IF NOT EXISTS users (" +
                                         "id INT AUTO_INCREMENT PRIMARY KEY," +
                                         "username VARCHAR(255) NOT NULL UNIQUE," +
                                         "password_hash VARCHAR(255) NOT NULL)";
            stmt.execute(createUsersTableSQL);
            LOGGER.info("Users table ensured.");

        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Failed to initialize database: " + e.getMessage(), e);
        }
    }

    // --- Student CRUD Operations ---

    /**
     * Adds a new student to the database.
     *
     * @param student The Student object to add. Its ID will be updated with the generated key.
     * @return true if the student was added successfully, false otherwise.
     */
    public boolean addStudent(Student student) {
        String sql = "INSERT INTO students (name, age, grade) VALUES (?, ?, ?)";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            pstmt.setString(1, student.getName());
            pstmt.setInt(2, student.getAge());
            pstmt.setString(3, student.getGrade());

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                try (ResultSet generatedKeys = pstmt.getGeneratedKeys()) {
                    if (generatedKeys.next()) {
                        student.setId(generatedKeys.getInt(1)); // Set the generated ID back to the student object
                        LOGGER.info("Student added: " + student.getName() + " with ID " + student.getId());
                        return true;
                    }
                }
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error adding student: " + e.getMessage(), e);
        }
        return false;
    }

    /**
     * Retrieves a student from the database by their ID.
     *
     * @param id The ID of the student to retrieve.
     * @return An Optional containing the Student object if found, or an empty Optional otherwise.
     */
    public Optional<Student> getStudentById(int id) {
        String sql = "SELECT id, name, age, grade FROM students WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setInt(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    Student student = new Student(
                            rs.getInt("id"),
                            rs.getString("name"),
                            rs.getInt("age"),
                            rs.getString("grade")
                    );
                    LOGGER.info("Retrieved student by ID: " + id);
                    return Optional.of(student);
                }
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error getting student by ID " + id + ": " + e.getMessage(), e);
        }
        return Optional.empty();
    }

    /**
     * Retrieves all students from the database.
     *
     * @return A list of all Student objects. Returns an empty list if no students are found or an error occurs.
     */
    public List<Student> getAllStudents() {
        List<Student> students = new ArrayList<>();
        String sql = "SELECT id, name, age, grade FROM students";
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement(); // No user input, so Statement is acceptable
             ResultSet rs = stmt.executeQuery(sql)) {
            while (rs.next()) {
                students.add(new Student(
                        rs.getInt("id"),
                        rs.getString("name"),
                        rs.getInt("age"),
                        rs.getString("grade")
                ));
            }
            LOGGER.info("Retrieved all students. Count: " + students.size());
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error getting all students: " + e.getMessage(), e);
        }
        return students;
    }

    /**
     * Updates an existing student's information in the database.
     *
     * @param student The Student object with updated information (ID must be valid).
     * @return true if the student was updated successfully, false otherwise.
     */
    public boolean updateStudent(Student student) {
        String sql = "UPDATE students SET name = ?, age = ?, grade = ? WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, student.getName());
            pstmt.setInt(2, student.getAge());
            pstmt.setString(3, student.getGrade());
            pstmt.setInt(4, student.getId());

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                LOGGER.info("Student updated: ID " + student.getId());
                return true;
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error updating student ID " + student.getId() + ": " + e.getMessage(), e);
        }
        return false;
    }

    /**
     * Deletes a student from the database by their ID.
     *
     * @param id The ID of the student to delete.
     * @return true if the student was deleted successfully, false otherwise.
     */
    public boolean deleteStudent(int id) {
        String sql = "DELETE FROM students WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setInt(1, id);

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                LOGGER.info("Student deleted: ID " + id);
                return true;
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error deleting student ID " + id + ": " + e.getMessage(), e);
        }
        return false;
    }

    // --- User CRUD Operations (for system authentication) ---

    /**
     * Adds a new user to the database.
     *
     * @param user The User object to add (should contain a hashed password). Its ID will be updated.
     * @return true if the user was added successfully, false otherwise.
     */
    public boolean addUser(User user) {
        String sql = "INSERT INTO users (username, password_hash) VALUES (?, ?)";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            pstmt.setString(1, user.getUsername());
            pstmt.setString(2, user.getPasswordHash()); // Store the BCrypt hashed password

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                try (ResultSet generatedKeys = pstmt.getGeneratedKeys()) {
                    if (generatedKeys.next()) {
                        user.setId(generatedKeys.getInt(1));
                        LOGGER.info("User added: " + user.getUsername() + " with ID " + user.getId());
                        return true;
                    }
                }
            }
        } catch (SQLException e) {
            // CRITICAL: Log error without exposing the password hash
            LOGGER.log(Level.SEVERE, "Error adding user '" + user.getUsername() + "': " + e.getMessage(), e);
        }
        return false;
    }

    /**
     * Retrieves a user from the database by their username.
     *
     * @param username The username of the user to retrieve.
     * @return An Optional containing the User object if found, or an empty Optional otherwise.
     */
    public Optional<User> getUserByUsername(String username) {
        String sql = "SELECT id, username, password_hash FROM users WHERE username = ?";
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, username);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    User user = new User(
                            rs.getInt("id"),
                            rs.getString("username"),
                            rs.getString("password_hash")
                    );
                    LOGGER.info("Retrieved user by username: " + username);
                    return Optional.of(user);
                }
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Error getting user by username '" + username + "': " + e.getMessage(), e);
        }
        return Optional.empty();
    }
}

