package com.example.sms;

import com.example.sms.model.Student;
import com.example.sms.model.User;
import com.example.sms.repository.DatabaseManager;
import com.example.sms.service.AuthService;

import java.util.List;
import java.util.Optional;
import java.util.Scanner;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Main class for the Student Management System.
 * Provides a command-line interface for user authentication and student CRUD operations.
 */
public class Main {
    private static final Logger LOGGER = Logger.getLogger(Main.class.getName());
    private static final Scanner scanner = new Scanner(System.in);
    private static DatabaseManager dbManager;
    private static AuthService authService;
    private static User currentUser = null; // Stores the currently authenticated user

    public static void main(String[] args) {
        // Configure logging to console for better readability
        System.setProperty("java.util.logging.SimpleFormatter.format",
                "[%1$tF %1$tT] [%4$-7s] %3$s - %5$s%n");
        LOGGER.setLevel(Level.INFO); // Set default logging level for the application

        dbManager = new DatabaseManager();
        authService = new AuthService(dbManager);

        // Ensure a default admin user exists for initial setup
        // This allows the system to be used immediately without manual DB insertion for users.
        if (dbManager.getUserByUsername("admin").isEmpty()) {
            System.out.println("No admin user found. Creating default admin user 'admin'.");
            System.out.print("Please enter an initial password for 'admin': ");
            String adminPassword = scanner.nextLine();
            if (authService.registerUser("admin", adminPassword)) {
                System.out.println("Default admin user 'admin' created successfully.");
            } else {
                System.err.println("Failed to create default admin user. Exiting application.");
                return;
            }
        }

        // Attempt to authenticate the user before allowing access to the system
        if (authenticateUser()) {
            runStudentManagementSystem();
        } else {
            System.out.println("Authentication failed. Exiting application.");
        }
        scanner.close();
    }

    /**
     * Handles user login process.
     *
     * @return true if authentication is successful, false otherwise.
     */
    private static boolean authenticateUser() {
        System.out.println("\n--- User Login ---");
        System.out.print("Enter username: ");
        String username = scanner.nextLine();
        System.out.print("Enter password: ");
        String password = scanner.nextLine(); // Password input is not masked for simplicity in CLI

        Optional<User> authenticatedUser = authService.authenticate(username, password);
        if (authenticatedUser.isPresent()) {
            currentUser = authenticatedUser.get();
            System.out.println("Welcome, " + currentUser.getUsername() + "!");
            return true;
        } else {
            System.out.println("Invalid username or password.");
            return false;
        }
    }

    /**
     * Runs the main loop for the Student Management System, displaying the menu
     * and processing user choices.
     */
    private static void runStudentManagementSystem() {
        int choice;
        do {
            printMenu();
            System.out.print("Enter your choice: ");
            try {
                choice = Integer.parseInt(scanner.nextLine());
                switch (choice) {
                    case 1:
                        addStudent();
                        break;
                    case 2:
                        viewStudent();
                        break;
                    case 3:
                        viewAllStudents();
                        break;
                    case 4:
                        updateStudent();
                        break;
                    case 5:
                        deleteStudent();
                        break;
                    case 6:
                        System.out.println("Logging out and exiting. Goodbye!");
                        break;
                    default:
                        System.out.println("Invalid choice. Please try again.");
                }
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter a number.");
                choice = 0; // Keep the loop running for invalid number format
            }
            System.out.println(); // New line for better readability after each operation
        } while (choice != 6);
    }

    /**
     * Prints the main menu options to the console.
     */
    private static void printMenu() {
        System.out.println("--- Student Management System ---");
        System.out.println("1. Add Student");
        System.out.println("2. View Student by ID");
        System.out.println("3. View All Students");
        System.out.println("4. Update Student");
        System.out.println("5. Delete Student");
        System.out.println("6. Logout and Exit");
        System.out.println("---------------------------------");
    }

    /**
     * Prompts the user for student details and adds a new student to the database.
     */
    private static void addStudent() {
        System.out.println("\n--- Add New Student ---");
        System.out.print("Enter student name: ");
        String name = scanner.nextLine();
        System.out.print("Enter student age: ");
        int age = readIntInput();
        if (age == -1) return; // Error in input, return to menu
        System.out.print("Enter student grade (e.g., A, B+, C): ");
        String grade = scanner.nextLine();

        Student newStudent = new Student(name, age, grade);
        if (dbManager.addStudent(newStudent)) {
            System.out.println("Student added successfully: " + newStudent);
        } else {
            System.out.println("Failed to add student.");
        }
    }

    /**
     * Prompts the user for a student ID and displays the student's details.
     */
    private static void viewStudent() {
        System.out.println("\n--- View Student by ID ---");
        System.out.print("Enter student ID: ");
        int id = readIntInput();
        if (id == -1) return;

        Optional<Student> student = dbManager.getStudentById(id);
        if (student.isPresent()) {
            System.out.println("Student found: " + student.get());
        } else {
            System.out.println("Student with ID " + id + " not found.");
        }
    }

    /**
     * Displays details of all students currently in the database.
     */
    private static void viewAllStudents() {
        System.out.println("\n--- All Students ---");
        List<Student> students = dbManager.getAllStudents();
        if (students.isEmpty()) {
            System.out.println("No students in the system.");
        } else {
            students.forEach(System.out::println);
        }
    }

    /**
     * Prompts the user for a student ID and allows updating their details.
     */
    private static void updateStudent() {
        System.out.println("\n--- Update Student ---");
