package com.example.sms.service;

import com.example.sms.model.User;
import com.example.sms.repository.DatabaseManager;
import org.mindrot.jbcrypt.BCrypt;

import java.util.Optional;
import java.util.logging.Logger;

/**
 * Service class for user authentication and registration using BCrypt for password hashing.
 */
public class AuthService {
    private static final Logger LOGGER = Logger.getLogger(AuthService.class.getName());
    private final DatabaseManager dbManager;

    public AuthService(DatabaseManager dbManager) {
        this.dbManager = dbManager;
    }

    /**
     * Hashes a plain-text password using BCrypt.
     *
     * @param plainPassword The plain-text password to hash.
     * @return The BCrypt hashed password string.
     */
    public String hashPassword(String plainPassword) {
        // BCrypt.gensalt() generates a new salt for each hash, making rainbow table attacks ineffective.
        return BCrypt.hashpw(plainPassword, BCrypt.gensalt());
    }

    /**
     * Verifies a plain-text password against a BCrypt hashed password.
     *
     * @param plainPassword The plain-text password provided by the user.
     * @param hashedPassword The BCrypt hashed password retrieved from the database.
     * @return true if the passwords match, false otherwise.
     */
    public boolean checkPassword(String plainPassword, String hashedPassword) {
        return BCrypt.checkpw(plainPassword, hashedPassword);
    }

    /**
     * Authenticates a user by username and plain-text password.
     *
     * @param username The username provided by the user.
     * @param password The plain-text password provided by the user.
     * @return An Optional containing the User object if authentication is successful,
     *         or an empty Optional if authentication fails (user not found or incorrect password).
     */
    public Optional<User> authenticate(String username, String password) {
        Optional<User> userOptional = dbManager.getUserByUsername(username);
        if (userOptional.isPresent()) {
            User user = userOptional.get();
            if (checkPassword(password, user.getPasswordHash())) {
                LOGGER.info("User '" + username + "' authenticated successfully.");
                return Optional.of(user);
            } else {
                // Log authentication failure without exposing the incorrect password
                LOGGER.warning("Authentication failed for user '" + username + "': Incorrect password.");
            }
        } else {
            LOGGER.warning("Authentication failed: User '" + username + "' not found.");
        }
        return Optional.empty();
    }

    /**
     * Registers a new user with a hashed password.
     *
     * @param username The username for the new user.
     * @param plainPassword The plain-text password for the new user.
     * @return true if the user was successfully registered, false if the username already exists or an error occurred.
     */
    public boolean registerUser(String username, String plainPassword) {
        if (dbManager.getUserByUsername(username).isPresent()) {
            LOGGER.warning("Registration failed: Username '" + username + "' already exists.");
            return false;
        }
        String hashedPassword = hashPassword(plainPassword);
        User newUser = new User(username, hashedPassword);
        boolean success = dbManager.addUser(newUser);
        if (success) {
            LOGGER.info("User '" + username + "' registered successfully.");
        } else {
            LOGGER.severe("Failed to register user '" + username + "'.");
        }
        return success;
    }
}

