import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { query } from '../config/db.js';
import dotenv from 'dotenv';
import logger from '../utils/logger.js';

dotenv.config();

const JWT_SECRET = process.env.JWT_SECRET;
const SALT_ROUNDS = 10;

export const registerUser = async (req, res, next) => {
  const { username, password } = req.body;

  if (!username || !password) {
    logger.warn('Registration attempt with missing username or password.');
    return res.status(400).json({ message: 'Username and password are required.' });
  }

  try {
    // Hash password
    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);

    // Insert user into database
    const result = await query(
      'INSERT INTO users (username, password_hash) VALUES ($1, $2) RETURNING id, username',
      [username, passwordHash]
    );

    const newUser = result.rows[0];
    logger.info(`User registered: ${newUser.username}`);
    res.status(201).json({ message: 'User registered successfully.', user: { id: newUser.id, username: newUser.username } });
  } catch (error) {
    if (error.code === '23505') { // Unique violation error code for PostgreSQL
      logger.warn(`Registration failed: Username '${username}' already exists.`);
      return res.status(409).json({ message: 'Username already exists.' });
    }
    logger.error(`Error during user registration for '${username}': ${error.message}`, { stack: error.stack });
    next(error); // Pass to error handling middleware
  }
};

export const loginUser = async (req, res, next) => {
  const { username, password } = req.body;

  if (!username || !password) {
    logger.warn('Login attempt with missing username or password.');
    return res.status(400).json({ message: 'Username and password are required.' });
  }

  try {
    // Find user by username
    const result = await query('SELECT id, username, password_hash FROM users WHERE username = $1', [username]);
    const user = result.rows[0];

    if (!user) {
      logger.warn(`Login failed: User '${username}' not found.`);
      return res.status(401).json({ message: 'Invalid credentials.' });
    }

    // Compare password
    const isPasswordValid = await bcrypt.compare(password, user.password_hash);

    if (!isPasswordValid) {
      logger.warn(`Login failed: Invalid password for user '${username}'.`);
      return res.status(401).json({ message: 'Invalid credentials.' });
    }

    // Generate JWT token
    const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, { expiresIn: '1h' });

    logger.info(`User logged in: ${user.username}`);
    res.status(200).json({ message: 'Login successful.', token, user: { id: user.id, username: user.username } });
  } catch (error) {
    logger.error(`Error during user login for '${username}': ${error.message}`, { stack: error.stack });
    next(error); // Pass to error handling middleware
  }
};
