export const createTransaction = async (req, res, next) => {
  const { type, category, amount, description, transaction_date } = req.body;
  const userId = req.user.id; // From auth middleware

  if (!type || !category || !amount || !transaction_date) {
    logger.warn(`Transaction creation failed for user ${userId}: Missing required fields.`);
    return res.status(400).json({ message: 'Type, category, amount, and transaction date are required.' });
  }
  if (isNaN(parseFloat(amount)) || parseFloat(amount) <= 0) {
    logger.warn(`Transaction creation failed for user ${userId}: Invalid amount '${amount}'.`);
    return res.status(400).json({ message: 'Amount must be a positive number.' });
  }

  try {
    const result = await query(
      'INSERT INTO transactions (user_id, type, category, amount, description, transaction_date) VALUES ($1, $2, $3, $4, $5, $6) RETURNING *',
      [userId, type, category, parseFloat(amount), description, transaction_date]
    );
    logger.info(`Transaction created for user ${userId}: ${result.rows[0].id}`);
    res.status(201).json(result.rows[0]);
  } catch (error) {
    logger.error(`Error creating transaction for user ${userId}: ${error.message}`, { stack: error.stack, body: req.body });
    next(error);
  }
};

export const getTransactions = async (req, res, next) => {
  const userId = req.user.id;
  const { type, category, startDate, endDate } = req.query;

  let sql = 'SELECT * FROM transactions WHERE user_id = $1';
  const params = [userId];
  let paramIndex = 2;

  if (type) {
    sql += ` AND type = $${paramIndex++}`;
    params.push(type);
  }
  if (category) {
    sql += ` AND category ILIKE $${paramIndex++}`; // Case-insensitive search
    params.push(`%${category}%`);
  }
  if (startDate) {
    sql += ` AND transaction_date >= $${paramIndex++}`;
    params.push(startDate);
  }
  if (endDate) {
    sql += ` AND transaction_date <= $${paramIndex++}`;
    params.push(endDate);
  }

  sql += ' ORDER BY transaction_date DESC, created_at DESC';

  try {
    const result = await query(sql, params);
    logger.info(`Fetched ${result.rows.length} transactions for user ${userId}.`);
    res.status(200).json(result.rows);
  } catch (error) {
    logger.error(`Error fetching transactions for user ${userId}: ${error.message}`, { stack: error.stack, query: req.query });
    next(error);
  }
};

export const getTransactionById = async (req, res, next) => {
  const { id } = req.params;
  const userId = req.user.id;

  try {
    const result = await query('SELECT * FROM transactions WHERE id = $1 AND user_id = $2', [id, userId]);
    const transaction = result.rows[0];

    if (!transaction) {
      logger.warn(`Transaction ${id} not found or not authorized for user ${userId}.`);
      return res.status(404).json({ message: 'Transaction not found or unauthorized.' });
    }
    logger.info(`Fetched transaction ${id} for user ${userId}.`);
    res.status(200).json(transaction);
  } catch (error) {
