document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = 'http://localhost:3000/api'; // Adjust if your backend runs on a different port/host

    // Auth Elements
    const registerUsernameInput = document.getElementById('register-username');
    const registerPasswordInput = document.getElementById('register-password');
    const registerBtn = document.getElementById('register-btn');
    const registerMessage = document.getElementById('register-message');

    const loginUsernameInput = document.getElementById('login-username');
    const loginPasswordInput = document.getElementById('login-password');
    const loginBtn = document.getElementById('login-btn');
    const logoutBtn = document.getElementById('logout-btn');
    const loginMessage = document.getElementById('login-message');

    const authSection = document.getElementById('auth-section');
    const appSection = document.getElementById('app-section');
    const currentUserSpan = document.getElementById('current-user');

    // Transaction Elements
    const transactionIdInput = document.getElementById('transaction-id');
    const transactionTypeSelect = document.getElementById('transaction-type');
    const transactionCategoryInput = document.getElementById('transaction-category');
    const transactionAmountInput = document.getElementById('transaction-amount');
    const transactionDescriptionInput = document.getElementById('transaction-description');
    const transactionDateInput = document.getElementById('transaction-date');
    const saveTransactionBtn = document.getElementById('save-transaction-btn');
    const cancelEditBtn = document.getElementById('cancel-edit-btn');
    const transactionMessage = document.getElementById('transaction-message');
    const transactionsTableBody = document.getElementById('transactions-table-body');

    // Filter Elements
    const filterTypeSelect = document.getElementById('filter-type');
    const filterCategoryInput = document.getElementById('filter-category');
    const filterStartDateInput = document.getElementById('filter-start-date');
    const filterEndDateInput = document.getElementById('filter-end-date');
    const applyFilterBtn = document.getElementById('apply-filter-btn');
    const clearFilterBtn = document.getElementById('clear-filter-btn');

    let currentToken = localStorage.getItem('token');
    let currentUsername = localStorage.getItem('username');

    const showMessage = (element, msg, isError = false) => {
        element.textContent = msg;
        element.className = `message ${isError ? 'error' : 'success'}`;
        setTimeout(() => {
            element.textContent = '';
            element.className = 'message';
        }, 5000);
    };

    const setAuthUI = () => {
        if (currentToken && currentUsername) {
            authSection.style.display = 'none';
            appSection.style.display = 'block';
            logoutBtn.style.display = 'inline-block';
            currentUserSpan.textContent = currentUsername;
            fetchTransactions();
        } else {
            authSection.style.display = 'block';
            appSection.style.display = 'none';
            logoutBtn.style.display = 'none';
            currentUserSpan.textContent = '';
            transactionsTableBody.innerHTML = '';
        }
    };

    const clearTransactionForm = () => {
        transactionIdInput.value = '';
        transactionTypeSelect.value = '';
        transactionCategoryInput.value = '';
        transactionAmountInput.value = '';
        transactionDescriptionInput.value = '';
        transactionDateInput.value = '';
        saveTransactionBtn.textContent = 'Save Transaction';
        cancelEditBtn.style.display = 'none';
    };

    const fetchTransactions = async () => {
        if (!currentToken) return;

        const type = filterTypeSelect.value;
        const category = filterCategoryInput.value;
        const startDate = filterStartDateInput.value;
        const endDate = filterEndDateInput.value;

        const queryParams = new URLSearchParams();
        if (type) queryParams.append('type', type);
        if (category) queryParams.append('category', category);
        if (startDate) queryParams.append('startDate', startDate);
        if (endDate) queryParams.append('endDate', endDate);

        try {
            const response = await fetch(`${API_BASE_URL}/transactions?${queryParams.toString()}`, {
                headers: {
                    'Authorization': `Bearer ${currentToken}`
                }
            });
            if (!response.ok) {
                if (response.status === 403 || response.status === 401) {
                    logoutUser();
                    showMessage(loginMessage, 'Session expired. Please log in again.', true);
                    return;
                }
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const transactions = await response.json();
            renderTransactions(transactions);
        } catch (error) {
            console.error('Error fetching transactions:', error);
            showMessage(transactionMessage, 'Failed to load transactions.', true);
        }
    };

    const renderTransactions = (transactions) => {
        transactionsTableBody.innerHTML = '';
        if (transactions.length === 0) {
            transactionsTableBody.innerHTML = '<tr><td colspan="6">No transactions found.</td></tr>';
            return;
        }
        transactions.forEach(transaction => {
            const row = transactionsTableBody.insertRow();
            row.innerHTML = `
                <td>${new Date(transaction.transaction_date).toLocaleDateString()}</td>
                <td>${transaction.type}</td>
                <td>${transaction.category}</td>
                <td>$${parseFloat(transaction.amount).toFixed(2)}</td>
                <td>${transaction.description || '-'}</td>
                <td class="actions">
                    <button class="edit-btn" data-id="${transaction.id}">Edit</button>
                    <button class="delete-btn" data-id="${transaction.id}">Delete</button>
                </td>
            `;
        });

        document.querySelectorAll('.edit-btn').forEach(button => {
            button.addEventListener('click', (e) => editTransaction(e.target.dataset.id));
        });
        document.querySelectorAll('.delete-btn').forEach(button => {
            button.addEventListener('click', (e) => deleteTransaction(e.target.dataset.id));
        });
    };

    const registerUser = async () => {
        const username = registerUsernameInput.value;
        const password = registerPasswordInput.value;

        try {
            const response = await fetch(`${API_BASE_URL}/auth/register`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password })
            });
            const data = await response.json();
            if (response.ok) {
                showMessage(registerMessage, data.message);
                registerUsernameInput.value = '';
                registerPasswordInput.value = '';
            } else {
                showMessage(registerMessage, data.message || 'Registration failed.', true);
            }
        } catch (error) {
            console.error('Registration error:', error);
            showMessage(registerMessage, 'An error occurred during registration.', true);
        }
    };

    const loginUser = async () => {
        const username = loginUsernameInput.value;
        const password = loginPasswordInput.value;

        try {
            const response = await fetch(`${API_BASE_URL}/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password })
            });
            const data = await response.json();
            if (response.ok) {
                currentToken = data.token;
                currentUsername = data.user.username;
                localStorage.setItem('token', currentToken);
                localStorage.setItem('username', currentUsername);
                showMessage(loginMessage, data.message);
                loginUsernameInput.value = '';
                loginPasswordInput.value = '';
                setAuthUI();
            } else {
                showMessage(loginMessage, data.message || 'Login failed.', true);
            }
        } catch (error) {
            console.error('Login error:', error);
            showMessage(loginMessage, 'An error occurred during login.', true);
        }
    };

    const logoutUser = () => {
        currentToken = null;
        currentUsername = null;
        localStorage.removeItem('token');
        localStorage.removeItem('username');
        showMessage(loginMessage, 'Logged out successfully.');
        setAuthUI();
        clearTransactionForm();
    };

    const saveTransaction = async () => {
        const id = transactionIdInput.value;
        const type = transactionTypeSelect.value;
        const category = transactionCategoryInput.value;
        const amount = parseFloat(transactionAmountInput.value);
        const description = transactionDescriptionInput.value;
        const transaction_date = transactionDateInput.value;

        if (!type || !category || isNaN(amount) || amount <= 0 || !transaction_date) {
            showMessage(transactionMessage, 'Please fill all required fields with valid data.', true);
            return;
        }

        const method = id ? 'PUT' : 'POST';
        const url = id ? `${API_BASE_URL}/transactions/${id}` : `${API_BASE_URL}/transactions`;

        try {
            const response = await fetch(url, {
                method: method,
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${currentToken}`
                },
                body: JSON.stringify({ type, category, amount, description, transaction_date })
            });
            const data = await response.json();
            if (response.ok) {
                showMessage(transactionMessage, id ? 'Transaction updated successfully!' : 'Transaction added successfully!');
                clearTransactionForm();
                fetchTransactions();
            } else {
                if (response.status === 403 || response.status === 401) {
                    logoutUser();
                    showMessage(loginMessage, 'Session expired. Please log in again.', true);
                    return;
                }
                showMessage(transactionMessage, data.message || 'Failed to save transaction.', true);
            }
        } catch (error) {
            console.error('Save transaction error:', error);
            showMessage(transactionMessage, 'An error occurred while saving the transaction.', true);
        }
    };

    const editTransaction = async (id) => {
        try {
            const response = await fetch(`${API_BASE_URL}/transactions/${id}`, {
                headers: {
                    'Authorization': `Bearer ${currentToken}`
                }
            });
            if (!response.ok) {
                if (response.status === 403 || response.status === 401) {
                    logoutUser();
                    showMessage(loginMessage, 'Session expired. Please log in again.', true);
                    return;
                }
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const transaction = await response.json();
            transactionIdInput.value = transaction.id;
            transactionTypeSelect.value = transaction.type;
            transactionCategoryInput.value = transaction.category;
            transactionAmountInput.value = parseFloat(transaction.amount);
            transactionDescriptionInput.value = transaction.description;
            transactionDateInput.value = new Date(transaction.transaction_date).toISOString().split('T')[0]; // Format to YYYY-MM-DD
            saveTransactionBtn.textContent = 'Update Transaction';
            cancelEditBtn.style.display = 'inline-block';
        } catch (error) {
            console.error('Error fetching transaction for edit:', error);
            showMessage(transactionMessage, 'Failed to load transaction for editing.', true);
        }
    };

    const deleteTransaction = async (id) => {
        if (!confirm('Are you sure you want to delete this transaction?')) return;

        try {
            const response = await fetch(`${API_BASE_URL}/transactions/${id}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': `Bearer ${currentToken}`
                }
            });
            if (response.ok) {
                showMessage(transactionMessage, 'Transaction deleted successfully!');
                fetchTransactions();
            } else {
                if (response.status === 403 || response.status === 401) {
                    logoutUser();
                    showMessage(loginMessage, 'Session expired. Please log in again.', true);
                    return;
                }
                const data = await response.json();
                showMessage(transactionMessage, data.message || 'Failed to delete transaction.', true);
            }
        } catch (error) {
            console.error('Delete transaction error:', error);
            showMessage(transactionMessage, 'An error occurred while deleting the transaction.', true);
        }
    };

    // Event Listeners
    registerBtn.addEventListener('click', registerUser);
    loginBtn.addEventListener('click', loginUser);
    logoutBtn.addEventListener('click', logoutUser);
    saveTransactionBtn.addEventListener('click', saveTransaction);
    cancelEditBtn.addEventListener('click', () => {
        clearTransactionForm();
        showMessage(transactionMessage, 'Edit cancelled.');
    });
    applyFilterBtn.addEventListener('click', fetchTransactions);
    clearFilterBtn.addEventListener('click', () => {
        filterTypeSelect.value = '';
        filterCategoryInput.value = '';
        filterStartDateInput.value = '';
        filterEndDateInput.value = '';
        fetchTransactions(); // Refetch all transactions
    });

    // Initial UI setup
    setAuthUI();
});
