// A simple logger utility. In a production app, consider libraries like Winston or Pino.
// This logger redacts sensitive information.

const LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3,
};

const CURRENT_LOG_LEVEL = LOG_LEVELS[process.env.LOG_LEVEL || 'INFO'];

const redactSensitiveData = (message, data) => {
  let redactedMessage = message;
  let redactedData = { ...data };

  // Redact common sensitive fields in message
  redactedMessage = redactedMessage.replace(/(password|token|jwt|secret|api_key|email)=[^&\s]+/gi, '$1=[REDACTED]');

  // Redact common sensitive fields in data object
  for (const key of Object.keys(redactedData)) {
    const lowerKey = key.toLowerCase();
    if (lowerKey.includes('password') || lowerKey.includes('token') || lowerKey.includes('jwt') || lowerKey.includes('secret') || lowerKey.includes('api_key') || lowerKey.includes('email')) {
      redactedData[key] = '[REDACTED]';
    }
  }
  return { redactedMessage, redactedData };
};

const log = (level, message, data = {}) => {
  if (LOG_LEVELS[level] < CURRENT_LOG_LEVEL) {
    return;
  }

  const timestamp = new Date().toISOString();
  const { redactedMessage, redactedData } = redactSensitiveData(message, data);

  const logEntry = {
    timestamp,
    level,
    message: redactedMessage,
    ...redactedData,
  };

  const logString = JSON.stringify(logEntry);

  switch (level) {
    case 'ERROR':
      console.error(logString);
      break;
    case 'WARN':
      console.warn(logString);
      break;
    case 'INFO':
      console.info(logString);
      break;
    case 'DEBUG':
      console.log(logString);
      break;
    default:
      console.log(logString);
  }
};

const logger = {
  debug: (message, data) => log('DEBUG', message, data),
  info: (message, data) => log('INFO', message, data),
  warn: (message, data) => log('WARN', message, data),
  error: (message, data) => log('ERROR', message, data),
};

export default logger;
