import java.sql.*;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class TransactionRepository {
    private static final Logger logger = LoggerFactory.getLogger(TransactionRepository.class);

    public Optional<Transaction> save(Transaction transaction) {
        String sql = "INSERT INTO TRANSACTIONS (account_id, type, amount, timestamp, description) VALUES (?, ?, ?, ?, ?)";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            pstmt.setLong(1, transaction.getAccountId());
            pstmt.setString(2, transaction.getType());
            pstmt.setBigDecimal(3, transaction.getAmount());
            pstmt.setTimestamp(4, Timestamp.valueOf(transaction.getTimestamp()));
            pstmt.setString(5, transaction.getDescription());

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                try (ResultSet rs = pstmt.getGeneratedKeys()) {
                    if (rs.next()) {
                        transaction.setId(rs.getLong(1));
                        return Optional.of(transaction);
                    }
                }
            }
        } catch (SQLException e) {
            logger.error("Error saving transaction: {}", e.getMessage());
        }
        return Optional.empty();
    }

    public Optional<Transaction> findById(long id) {
        String sql = "SELECT id, account_id, type, amount, timestamp, description FROM TRANSACTIONS WHERE id = ?";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setLong(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(mapRowToTransaction(rs));
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding transaction by id {}: {}", id, e.getMessage());
        }
        return Optional.empty();
    }

    public List<Transaction> findByAccountId(long accountId) {
        List<Transaction> transactions = new ArrayList<>();
        String sql = "SELECT id, account_id, type, amount, timestamp, description FROM TRANSACTIONS WHERE account_id = ? ORDER BY timestamp DESC";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setLong(1, accountId);
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    transactions.add(mapRowToTransaction(rs));
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding transactions by account id {}: {}", accountId, e.getMessage());
        }
        return transactions;
    }

    private Transaction mapRowToTransaction(ResultSet rs) throws SQLException {
        return new Transaction(
                rs.getLong("id"),
                rs.getLong("account_id"),
                rs.getString("type"),
                rs.getBigDecimal("amount"),
                rs.getTimestamp("timestamp").toLocalDateTime(),
                rs.getString("description")
        );
    }
}
