package com.bank.service;

import com.bank.model.Account;
import com.bank.model.Customer;
import com.bank.model.User;
import com.bank.repository.AccountRepository;
import com.bank.repository.CustomerRepository;
import com.bank.repository.UserRepository;
import com.bank.security.PasswordUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

public class AdminService {
    private static final Logger logger = LoggerFactory.getLogger(AdminService.class);

    private final UserRepository userRepository;
    private final CustomerRepository customerRepository;
    private final AccountRepository accountRepository;

    public AdminService(UserRepository userRepository, CustomerRepository customerRepository, AccountRepository accountRepository) {
        this.userRepository = userRepository;
        this.customerRepository = customerRepository;
        this.accountRepository = accountRepository;
    }

    /**
     * Creates a new user with a specified role and optionally a customer profile.
     *
     * @param username The desired username.
     * @param password The plain-text password.
     * @param role     The role of the user (CUSTOMER or ADMIN).
     * @param name     Customer name (if role is CUSTOMER).
     * @param address  Customer address (if role is CUSTOMER).
     * @param phone    Customer phone (if role is CUSTOMER).
     * @return The created User object, or Optional.empty() if creation fails.
     */
    public Optional<User> createUserAndCustomer(String username, String password, User.Role role, String name, String address, String phone) {
        if (userRepository.findByUsername(username).isPresent()) {
            logger.warn("Attempted to create user with existing username: {}", username);
            return Optional.empty(); // Username already exists
        }

        String hashedPassword = PasswordUtil.hashPassword(password);
        User newUser = new User(username, hashedPassword, role);
        Optional<User> savedUser = userRepository.save(newUser);

        if (savedUser.isPresent()) {
            logger.info("User created: {}", savedUser.get().getUsername());
            if (role == User.Role.CUSTOMER) {
                Customer newCustomer = new Customer(savedUser.get().getId(), name, address, phone);
                Optional<Customer> savedCustomer = customerRepository.save(newCustomer);
                if (savedCustomer.isPresent()) {
                    logger.info("Customer profile created for user: {}", savedUser.get().getUsername());
                    return savedUser;
                } else {
                    logger.error("Failed to create customer profile for user: {}", savedUser.get().getUsername());
                    // Potentially roll back user creation here in a real transaction system
                    return Optional.empty();
                }
            }
            return savedUser;
        }
        logger.error("Failed to create user: {}", username);
        return Optional.empty();
    }

    /**
     * Creates a new bank account for an existing customer.
     *
     * @param customerId    The ID of the customer.
     * @param accountType   The type of account (e.g., "SAVINGS", "CHECKING").
     * @param initialBalance The initial balance for the account.
     * @return The created Account object, or Optional.empty() if creation fails.
     */
    public Optional<Account> createAccount(long customerId, String accountType, BigDecimal initialBalance) {
        if (customerRepository.findById(customerId).isEmpty()) {
            logger.warn("Attempted to create account for non-existent customer ID: {}", customerId);
            return Optional.empty();
        }
        if (initialBalance.compareTo(BigDecimal.ZERO) < 0) {
            logger.warn("Attempted to create account with negative initial balance for customer ID: {}", customerId);
            return Optional.empty();
        }

        String accountNumber = generateUniqueAccountNumber();
        Account newAccount = new Account(customerId, accountNumber, accountType, initialBalance);
        Optional<Account> savedAccount = accountRepository.save(newAccount);

        if (savedAccount.isPresent()) {
            logger.info("Account created for customer ID {}: {}", customerId, savedAccount.get().getAccountNumber());
        } else {
            logger.error("Failed to create account for customer ID: {}", customerId);
        }
        return savedAccount;
    }

    /**
     * Retrieves a list of all customers in the system.
     *
     * @return A list of Customer objects.
     */
    public List<Customer> getAllCustomers() {
        return customerRepository.findAll();
    }

    /**
     * Retrieves a list of all accounts in the system.
     *
     * @return A list of Account objects.
     */
    public List<Account> getAllAccounts() {
        return accountRepository.findAll();
    }

    private String generateUniqueAccountNumber() {
        // Simple UUID-based account number. In a real system, this would involve more robust generation and collision checking.
        String accountNumber = UUID.randomUUID().toString().replace("-", "").substring(0, 10).toUpperCase();
        // Basic check for uniqueness, though collisions are highly unlikely with UUID substring
        while (accountRepository.findByAccountNumber(accountNumber).isPresent()) {
            accountNumber = UUID.randomUUID().toString().replace("-", "").substring(0, 10).toUpperCase();
        }
        return accountNumber;
    }
}
