package com.bank.service;

import com.bank.model.Account;
import com.bank.model.Transaction;
import com.bank.repository.AccountRepository;
import com.bank.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

public class BankService {
    private static final Logger logger = LoggerFactory.getLogger(BankService.class);

    private final AccountRepository accountRepository;
    private final TransactionRepository transactionRepository;

    public BankService(AccountRepository accountRepository, TransactionRepository transactionRepository) {
        this.accountRepository = accountRepository;
        this.transactionRepository = transactionRepository;
    }

    /**
     * Deposits money into an account.
     *
     * @param accountNumber The account number to deposit into.
     * @param amount        The amount to deposit.
     * @return true if deposit is successful, false otherwise.
     */
    public boolean deposit(String accountNumber, BigDecimal amount) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            logger.warn("Attempted to deposit non-positive amount: {}", amount);
            return false;
        }

        Optional<Account> accountOpt = accountRepository.findByAccountNumber(accountNumber);
        if (accountOpt.isEmpty()) {
            logger.warn("Deposit failed: Account not found for account number {}", accountNumber);
            return false;
        }

        Account account = accountOpt.get();
        BigDecimal newBalance = account.getBalance().add(amount);

        if (accountRepository.updateBalance(account.getId(), newBalance)) {
            account.setBalance(newBalance); // Update in-memory object
            Transaction transaction = new Transaction(
                    account.getId(),
                    "DEPOSIT",
                    amount,
                    LocalDateTime.now(),
                    "Deposit to account " + accountNumber
            );
            transactionRepository.save(transaction);
            logger.info("Deposit successful for account {}. New balance: {}", accountNumber, newBalance);
            return true;
        }
        logger.error("Deposit failed for account {}: Could not update balance in DB.", accountNumber);
        return false;
    }

    /**
     * Withdraws money from an account.
     *
     * @param accountNumber The account number to withdraw from.
     * @param amount        The amount to withdraw.
     * @return true if withdrawal is successful, false otherwise.
     */
    public boolean withdraw(String accountNumber, BigDecimal amount) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            logger.warn("Attempted to withdraw non-positive amount: {}", amount);
            return false;
        }

        Optional<Account> accountOpt = accountRepository.findByAccountNumber(accountNumber);
        if (accountOpt.isEmpty()) {
            logger.warn("Withdrawal failed: Account not found for account number {}", accountNumber);
            return false;
        }

        Account account = accountOpt.get();
        if (account.getBalance().compareTo(amount) < 0) {
            logger.warn("Withdrawal failed for account {}: Insufficient funds. Current balance: {}, Attempted withdrawal: {}",
                    accountNumber, account.getBalance(), amount);
            return false; // Insufficient funds
        }

        BigDecimal newBalance = account.getBalance().subtract(amount);

        if (accountRepository.updateBalance(account.getId(), newBalance)) {
            account.setBalance(newBalance); // Update in-memory object
            Transaction transaction = new Transaction(
                    account.getId(),
                    "WITHDRAWAL",
                    amount,
                    LocalDateTime.now(),
                    "Withdrawal from account " + accountNumber
            );
            transactionRepository.save(transaction);
            logger.info("Withdrawal successful for account {}. New balance: {}", accountNumber, newBalance);
            return true;
        }
        logger.error("Withdrawal failed for account {}: Could not update balance in DB.", accountNumber);
        return false;
    }

    /**
     * Transfers money from one account to another.
     *
     * @param fromAccountNumber The source account number.
     * @param toAccountNumber   The destination account number.
     * @param amount            The amount to transfer.
     * @return true if transfer is successful, false otherwise.
     */
    public boolean transfer(String fromAccountNumber, String toAccountNumber, BigDecimal amount) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            logger.warn("Attempted to transfer non-positive amount: {}", amount);
            return false;
        }
        if (fromAccountNumber.equals(toAccountNumber)) {
            logger.warn("Attempted to transfer money to the same account: {}", fromAccountNumber);
            return false;
        }

        Optional<Account> fromAccountOpt = accountRepository.findByAccountNumber(fromAccountNumber);
        Optional<Account> toAccountOpt = accountRepository.findByAccountNumber(toAccountNumber);

        if (fromAccountOpt.isEmpty()) {
            logger.warn("Transfer failed: Source account not found for account number {}", fromAccountNumber);
            return false;
        }
        if (toAccountOpt.isEmpty()) {
            logger.warn("Transfer failed: Destination account not found for account number {}", toAccountNumber);
            return false;
        }

        Account fromAccount = fromAccountOpt.get();
        Account toAccount = toAccountOpt.get();

        if (fromAccount.getBalance().compareTo(amount) < 0) {
            logger.warn("Transfer failed from account {}: Insufficient funds. Current balance: {}, Attempted transfer: {}",
                    fromAccountNumber, fromAccount.getBalance(), amount);
            return false; // Insufficient funds
        }

        // Perform withdrawal from source
        BigDecimal newFromBalance = fromAccount.getBalance().subtract(amount);
        if (!accountRepository.updateBalance(fromAccount.getId(), newFromBalance)) {
            logger.error("Transfer failed: Could not update source account balance for {}", fromAccountNumber);
            return false;
        }
        fromAccount.setBalance(newFromBalance); // Update in-memory object

        // Perform deposit to destination
        BigDecimal newToBalance = toAccount.getBalance().add(amount);
        if (!accountRepository.updateBalance(toAccount.getId(), newToBalance)) {
            logger.error("Transfer failed: Could not update destination account balance for {}. Rolling back source account.", toAccountNumber);
            // Attempt to roll back source account balance if destination update fails
            accountRepository.updateBalance(fromAccount.getId(), fromAccount.getBalance().add(amount));
            return false;
        }
        toAccount.setBalance(newToBalance); // Update in-memory object

        // Record transactions
        transactionRepository.save(new Transaction(
                fromAccount.getId(),
                "TRANSFER_OUT",
                amount,
                LocalDateTime.now(),
                "Transfer to account " + toAccountNumber
        ));
        transactionRepository.save(new Transaction(
                toAccount.getId(),
                "TRANSFER_IN",
                amount,
                LocalDateTime.now(),
                "Transfer from account " + fromAccountNumber
        ));

        logger.info("Transfer successful from {} to {}. Amount: {}", fromAccountNumber, toAccountNumber, amount);
        return true;
    }

    /**
     * Retrieves the current balance of an account.
     *
     * @param accountNumber The account number.
     * @return The balance of the account, or Optional.empty() if account not found.
     */
    public Optional<BigDecimal> getAccountBalance(String accountNumber) {
        return accountRepository.findByAccountNumber(accountNumber)
                .map(Account::getBalance);
    }

    /**
     * Retrieves all transactions for a given account.
     *
     * @param accountNumber The account number.
     * @return A list of Transaction objects for the account.
     */
    public List<Transaction> getAccountTransactions(String accountNumber) {
        Optional<Account> accountOpt = accountRepository.findByAccountNumber(accountNumber);
        if (accountOpt.isPresent()) {
            return transactionRepository.findByAccountId(accountOpt.get().getId());
        }
        logger.warn("Could not retrieve transactions: Account not found for account number {}", accountNumber);
        return List.of(); // Return empty list if account not found
    }

    /**
     * Retrieves all accounts associated with a customer ID.
     * @param customerId The ID of the customer.
     * @return A list of Account objects.
     */
    public List<Account> getCustomerAccounts(long customerId) {
        return accountRepository.findByCustomerId(customerId);
    }
}
