package com.bank.repository;

import com.bank.model.Account;
import com.bank.util.DatabaseUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class AccountRepository {
    private static final Logger logger = LoggerFactory.getLogger(AccountRepository.class);

    public Optional<Account> save(Account account) {
        String sql = "INSERT INTO ACCOUNTS (customer_id, account_number, account_type, balance) VALUES (?, ?, ?, ?)";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            pstmt.setLong(1, account.getCustomerId());
            pstmt.setString(2, account.getAccountNumber());
            pstmt.setString(3, account.getAccountType());
            pstmt.setBigDecimal(4, account.getBalance());

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                try (ResultSet rs = pstmt.getGeneratedKeys()) {
                    if (rs.next()) {
                        account.setId(rs.getLong(1));
                        return Optional.of(account);
                    }
                }
            }
        } catch (SQLException e) {
            logger.error("Error saving account: {}", e.getMessage());
        }
        return Optional.empty();
    }

    public Optional<Account> findById(long id) {
        String sql = "SELECT id, customer_id, account_number, account_type, balance FROM ACCOUNTS WHERE id = ?";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setLong(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(mapRowToAccount(rs));
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding account by id {}: {}", id, e.getMessage());
        }
        return Optional.empty();
    }

    public Optional<Account> findByAccountNumber(String accountNumber) {
        String sql = "SELECT id, customer_id, account_number, account_type, balance FROM ACCOUNTS WHERE account_number = ?";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, accountNumber);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(mapRowToAccount(rs));
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding account by account number {}: {}", accountNumber, e.getMessage());
        }
        return Optional.empty();
    }

    public List<Account> findByCustomerId(long customerId) {
        List<Account> accounts = new ArrayList<>();
        String sql = "SELECT id, customer_id, account_number, account_type, balance FROM ACCOUNTS WHERE customer_id = ?";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setLong(1, customerId);
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    accounts.add(mapRowToAccount(rs));
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding accounts by customer id {}: {}", customerId, e.getMessage());
        }
        return accounts;
    }

    public List<Account> findAll() {
        List<Account> accounts = new ArrayList<>();
        String sql = "SELECT id, customer_id, account_number, account_type, balance FROM ACCOUNTS";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql);
             ResultSet rs = pstmt.executeQuery()) {

            while (rs.next()) {
                accounts.add(mapRowToAccount(rs));
            }
        } catch (SQLException e) {
            logger.error("Error finding all accounts: {}", e.getMessage());
        }
        return accounts;
    }

    public boolean updateBalance(long accountId, BigDecimal newBalance) {
        String sql = "UPDATE ACCOUNTS SET balance = ? WHERE id = ?";
        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setBigDecimal(1, newBalance);
            pstmt.setLong(2, accountId);
            int affectedRows = pstmt.executeUpdate();
            return affectedRows > 0;
        } catch (SQLException e) {
            logger.error("Error updating balance for account id {}: {}", accountId, e.getMessage());
        }
        return false;
    }

    private Account mapRowToAccount(ResultSet rs) throws SQLException {
        return new Account(
                rs.getLong("id"),
                rs.getLong("customer_id"),
                rs.getString("account_number"),
                rs.getString("account_type"),
                rs.getBigDecimal("balance")
        );
    }
}
