package com.bank.security;

import org.mindrot.jbcrypt.BCrypt;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PasswordUtil {
    private static final Logger logger = LoggerFactory.getLogger(PasswordUtil.class);

    /**
     * Hashes a plain-text password using BCrypt.
     *
     * @param plainTextPassword The password in plain text.
     * @return The BCrypt hashed password.
     */
    public static String hashPassword(String plainTextPassword) {
        if (plainTextPassword == null || plainTextPassword.isEmpty()) {
            logger.warn("Attempted to hash a null or empty password.");
            throw new IllegalArgumentException("Password cannot be null or empty.");
        }
        return BCrypt.hashpw(plainTextPassword, BCrypt.gensalt());
    }

    /**
     * Verifies a plain-text password against a BCrypt hashed password.
     *
     * @param plainTextPassword The password in plain text.
     * @param hashedPassword    The BCrypt hashed password from storage.
     * @return true if the password matches, false otherwise.
     */
    public static boolean verifyPassword(String plainTextPassword, String hashedPassword) {
        if (plainTextPassword == null || hashedPassword == null) {
            logger.warn("Attempted to verify with null plainTextPassword or hashedPassword.");
            return false;
        }
        try {
            return BCrypt.checkpw(plainTextPassword, hashedPassword);
        } catch (IllegalArgumentException e) {
            logger.error("Error verifying password (likely invalid hash format): {}", e.getMessage());
            return false;
        }
    }
}
