package com.bank.util;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

public class ConfigUtil {
    private static final Logger logger = LoggerFactory.getLogger(ConfigUtil.class);
    private static final Properties properties = new Properties();
    private static final String CONFIG_FILE = "config.properties";

    static {
        try (InputStream input = ConfigUtil.class.getClassLoader().getResourceAsStream(CONFIG_FILE)) {
            if (input == null) {
                logger.error("Sorry, unable to find {}", CONFIG_FILE);
                throw new RuntimeException("Configuration file not found: " + CONFIG_FILE);
            }
            properties.load(input);
        } catch (IOException ex) {
            logger.error("Error loading configuration from {}: {}", CONFIG_FILE, ex.getMessage());
            throw new RuntimeException("Failed to load configuration", ex);
        }
    }

    /**
     * Retrieves a property value from config.properties.
     *
     * @param key The key of the property.
     * @return The value of the property.
     * @throws RuntimeException if the key is not found.
     */
    public static String getProperty(String key) {
        String value = properties.getProperty(key);
        if (value == null) {
            logger.error("Configuration key '{}' not found in {}", key, CONFIG_FILE);
            throw new RuntimeException("Configuration key not found: " + key);
        }
        return value;
    }

    /**
     * Retrieves a property value from config.properties with a default value.
     *
     * @param key The key of the property.
     * @param defaultValue The default value to return if the key is not found.
     * @return The value of the property or the default value.
     */
    public static String getProperty(String key, String defaultValue) {
        return properties.getProperty(key, defaultValue);
    }
}
