package com.bank.util;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;

public class DatabaseUtil {
    private static final Logger logger = LoggerFactory.getLogger(DatabaseUtil.class);
    private static final String DB_URL = ConfigUtil.getProperty("db.url");
    private static final String DB_USER = ConfigUtil.getProperty("db.user");
    private static final String DB_PASSWORD = ConfigUtil.getProperty("db.password");

    static {
        initializeDatabase();
    }

    private static void initializeDatabase() {
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
             Statement stmt = conn.createStatement()) {

            // Create USERS table
            stmt.execute("CREATE TABLE IF NOT EXISTS USERS (" +
                         "id BIGINT AUTO_INCREMENT PRIMARY KEY," +
                         "username VARCHAR(50) NOT NULL UNIQUE," +
                         "password_hash VARCHAR(100) NOT NULL," +
                         "role VARCHAR(20) NOT NULL" +
                         ")");
            logger.info("Table USERS ensured to exist.");

            // Create CUSTOMERS table
            stmt.execute("CREATE TABLE IF NOT EXISTS CUSTOMERS (" +
                         "id BIGINT AUTO_INCREMENT PRIMARY KEY," +
                         "user_id BIGINT NOT NULL UNIQUE," +
                         "name VARCHAR(100) NOT NULL," +
                         "address VARCHAR(255)," +
                         "phone VARCHAR(20)," +
                         "FOREIGN KEY (user_id) REFERENCES USERS(id)" +
                         ")");
            logger.info("Table CUSTOMERS ensured to exist.");

            // Create ACCOUNTS table
            stmt.execute("CREATE TABLE IF NOT EXISTS ACCOUNTS (" +
                         "id BIGINT AUTO_INCREMENT PRIMARY KEY," +
                         "customer_id BIGINT NOT NULL," +
                         "account_number VARCHAR(20) NOT NULL UNIQUE," +
                         "account_type VARCHAR(50) NOT NULL," +
                         "balance DECIMAL(19, 4) NOT NULL," +
                         "FOREIGN KEY (customer_id) REFERENCES CUSTOMERS(id)" +
                         ")");
            logger.info("Table ACCOUNTS ensured to exist.");

            // Create TRANSACTIONS table
            stmt.execute("CREATE TABLE IF NOT EXISTS TRANSACTIONS (" +
                         "id BIGINT AUTO_INCREMENT PRIMARY KEY," +
                         "account_id BIGINT NOT NULL," +
                         "type VARCHAR(50) NOT NULL," +
                         "amount DECIMAL(19, 4) NOT NULL," +
                         "timestamp TIMESTAMP NOT NULL," +
                         "description VARCHAR(255)," +
                         "FOREIGN KEY (account_id) REFERENCES ACCOUNTS(id)" +
