    public static void main(String[] args) {
        // Initialize database and repositories
        DatabaseUtil.initializeDatabase(); // Ensure schema is created
        userRepository = new UserRepository();
        customerRepository = new CustomerRepository();
        accountRepository = new AccountRepository();
        transactionRepository = new TransactionRepository();

        // Initialize services
        adminService = new AdminService(userRepository, customerRepository, accountRepository);
        bankService = new BankService(accountRepository, transactionRepository);

        // Create a default admin user if not exists
        if (userRepository.findByUsername("admin").isEmpty()) {
            adminService.createUserAndCustomer("admin", "adminpass", User.Role.ADMIN, "Admin User", "Admin Address", "555-1234");
            logger.info("Default admin user created: username 'admin', password 'adminpass'");
        }

        // Main application loop
        while (true) {
            System.out.println("\n--- Bank Management System ---");
            if (currentUser == null) {
                showLoginMenu();
