        if (userOpt.isPresent() && PasswordUtil.verifyPassword(password, userOpt.get().getPasswordHash())) {
            currentUser = userOpt.get();
            logger.info("User '{}' logged in successfully with role {}", currentUser.getUsername(), currentUser.getRole());
            System.out.println("Login successful! Welcome, " + currentUser.getUsername() + " (" + currentUser.getRole() + ")");
