import java.util.List;

public class BookDAO {
    private static final Logger logger = LoggerFactory.getLogger(BookDAO.class);

    public Book findBookById(int id) throws SQLException {
        String sql = "SELECT id, title, author, is_available FROM books WHERE id = ?";
        try (Connection conn = DatabaseManager.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setInt(1, id);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return new Book(
                            rs.getInt("id"),
                            rs.getString("title"),
                            rs.getString("author"),
                            rs.getBoolean("is_available")
                    );
                }
            }
        } catch (SQLException e) {
            logger.error("Error finding book by ID {}: {}", id, e.getMessage());
            throw e;
        }
        return null;
    }

    public List<Book> getAllBooks() throws SQLException {
        List<Book> books = new ArrayList<>();
        String sql = "SELECT id, title, author, is_available FROM books ORDER BY title";
        try (Connection conn = DatabaseManager.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql);
             ResultSet rs = pstmt.executeQuery()) {
            while (rs.next()) {
                books.add(new Book(
                        rs.getInt("id"),
                        rs.getString("title"),
                        rs.getString("author"),
                        rs.getBoolean("is_available")
                ));
            }
        } catch (SQLException e) {
            logger.error("Error getting all books: {}", e.getMessage());
            throw e;
        }
        return books;
    }

    public boolean createBook(Book book) throws SQLException {
        String sql = "INSERT INTO books (title, author, is_available) VALUES (?, ?, ?)";
        try (Connection conn = DatabaseManager.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            pstmt.setString(1, book.getTitle());
            pstmt.setString(2, book.getAuthor());
            pstmt.setBoolean(3, book.isAvailable());

            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                try (ResultSet generatedKeys = pstmt.getGeneratedKeys()) {
                    if (generatedKeys.next()) {
                        book.setId(generatedKeys.getInt(1));
                    }
                }
                logger.info("Book created: {} by {}", book.getTitle(), book.getAuthor());
                return true;
            }
        } catch (SQLException e) {
            logger.error("Error creating book {}: {}", book.getTitle(), e.getMessage());
            throw e;
        }
        return false;
    }

    public boolean updateBookAvailability(int bookId, boolean isAvailable) throws SQLException {
        String sql = "UPDATE books SET is_available = ? WHERE id = ?";
        try (Connection conn = DatabaseManager.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setBoolean(1, isAvailable);
            pstmt.setInt(2, bookId);
            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                logger.info("Book ID {} availability updated to {}", bookId, isAvailable);
                return true;
            }
        } catch (SQLException e) {
            logger.error("Error updating availability for book ID {}: {}", bookId, e.getMessage());
            throw e;
        }
        return false;
    }

    public boolean deleteBook(int bookId) throws SQLException {
        String sql = "DELETE FROM books WHERE id = ?";
        try (Connection conn = DatabaseManager.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setInt(1, bookId);
            int affectedRows = pstmt.executeUpdate();
            if (affectedRows > 0) {
                logger.info("Book ID {} deleted.", bookId);
                return true;
            }
        } catch (SQLException e) {
            logger.error("Error deleting book ID {}: {}", bookId, e.getMessage());
            throw e;
        }
